package io.github.docmorphic.cmuxapp

import org.junit.Assert.*
import org.junit.Test
import java.util.Locale

class MarkdownWebThemeTest {
    @Test fun neutralSystemBackgroundMatchesNativeContrastTargets() {
        // Independent inverse-sRGB solutions of the native contrast targets against white/black,
        // rounded to the native CSS precision (not values generated by this implementation).
        val light = MarkdownWebTheme.resolve(false, -1)
        assertEquals("rgba(0, 0, 0, 0.027)", light.muted)
        assertEquals("rgba(0, 0, 0, 0.081)", light.neutral)
        assertEquals("rgba(0, 0, 0, 0.154)", light.border)
        assertEquals("rgba(0, 0, 0, 0.108)", light.mutedBorder)
        val dark = MarkdownWebTheme.resolve(true, 0xff000000.toInt())
        assertEquals("rgba(255, 255, 255, 0.056)", dark.muted)
        assertEquals("rgba(255, 255, 255, 0.141)", dark.neutral)
        assertEquals("rgba(255, 255, 255, 0.237)", dark.border)
        assertEquals("rgba(255, 255, 255, 0.166)", dark.mutedBorder)
    }

    @Test fun overlaysResolveAgainstViewerSurfaceAndKeepCssDecimalLocaleIndependent() {
        val previous = Locale.getDefault()
        try {
            Locale.setDefault(Locale.GERMANY)
            val black = MarkdownWebTheme.resolve(true, 0xff000000.toInt())
            val surface = MarkdownWebTheme.resolve(true, 0xff0b0c0e.toInt())
            assertNotEquals(black, surface)
            assertTrue(surface.border.matches(Regex("rgba\\(255, 255, 255, 0\\.[0-9]{3}\\)")))
        } finally { Locale.setDefault(previous) }
    }
}
